<?php
namespace App\Services;
use App\Models\{HomeRemedy,HomeRemedyCategory,HomeRemedyIngredient};
use Illuminate\Support\Facades\DB;
class HomeRemedyImportService {
 public function import(string $path,string $mode='create_update'):array { $rows=SpreadsheetService::parseSpreadsheet($path); $out=['total'=>count($rows),'created'=>0,'updated'=>0,'skipped'=>0,'failed'=>0,'errors'=>[]]; foreach($rows as $i=>$row){$line=$i+2; try{ $errors=[]; foreach(['title_en','title_hi','category'] as $f)if(trim((string)($row[$f]??''))==='')$errors[]="$f is required"; if(!in_array($row['evidence_level']??'traditional',['traditional','limited','supportive','moderate','strong','not_recommended'],true))$errors[]='evidence_level is invalid'; $cat=HomeRemedyCategory::where('name_en',$row['category']??'')->orWhere('slug',$row['category']??'')->first(); if(!$cat)$errors[]='category "'.($row['category']??'').'" was not found'; if(($row['is_published']??'0') && empty($row['suitable_for_en']))$errors[]='suitable_for_en is required for published remedies'; if($errors){$out['failed']++;$out['errors'][$line]=$errors;continue;} DB::transaction(function()use($row,$cat,$mode,&$out){$data=array_intersect_key($row,array_flip((new HomeRemedy)->getFillable())); $data['category_id']=$cat->id; foreach(['is_featured','is_published'] as $b)$data[$b]=filter_var($row[$b]??false,FILTER_VALIDATE_BOOLEAN); $existing=!empty($row['id'])?HomeRemedy::find($row['id']):HomeRemedy::where('slug',$row['slug']??'')->first(); if($existing && $mode==='create_only')throw new \RuntimeException('record already exists'); if(!$existing && $mode==='update_only')throw new \RuntimeException('record does not exist'); $r=$existing??new HomeRemedy; $r->fill($data); $r->slug=$r->slug ?: \Illuminate\Support\Str::slug($r->title_en); $r->save(); if($existing)$out['updated']++;else$out['created']++; if(array_key_exists('ingredients',$row)){ $ids=[]; foreach(array_filter(array_map('trim',explode('|',(string)$row['ingredients']))) as $name){$ing=HomeRemedyIngredient::where('name_en',$name)->orWhere('slug',\Illuminate\Support\Str::slug($name))->first(); if($ing)$ids[$ing->id]=[];} $r->ingredients()->sync($ids); }}); }catch(\Throwable $e){$out['failed']++;$out['errors'][$line]=[$e->getMessage()];}} return $out; }
}
